54: import { getToken } from '@/utils/auth.js'
55: import AppendixFileThumbnail from '@/components/AnnexUpload/components/AppendixFileThumbnail.vue'
56: import uploadPlaceholderImg from '@/assets/images/annex/upload-file-placeholder.png'
57: import appendixViewEmptyImg from '@/assets/images/annex/appendix-view-empty.png'
58: import {
59:   APPENDIX_REQUIREMENT_CARD_MIN_WIDTH,
60:   APPENDIX_REQUIREMENT_GRID_GAP,
61:   APPENDIX_THUMB_SIZE,
62:   APPENDIX_TITLE_TO_THUMB_GAP,
63:   isAppendixImage
64: } from '@/utils/appendix.js'
65: 
66: let appendixUid = 0
67: 
68: function nextAppendixUid() {
69:   appendixUid += 1
70:   return `standalone-appendix-${appendixUid}`
71: }
72: 
73: function extractFileName(path) {
74:   if (!path) return ''
75:   const raw = String(path).split('?')[0]
76:   const name = raw.lastIndexOf('/') > -1 ? raw.slice(raw.lastIndexOf('/') + 1) : raw
77:   try {
78:     return decodeURIComponent(name)
79:   } catch {
80:     return name
81:   }
82: }
83: 
84: export default {
85:   name: 'StandaloneAppendixField',
86:   components: { AppendixFileThumbnail },
87:   props: {
88:     value: {
89:       type: [String, Object, Array],
90:       default: ''
91:     },
92:     label: {
93:       type: String,
94:       default: ''
95:     },
96:     required: {
97:       type: Boolean,
98:       default: false
99:     },
100:     limit: {
101:       type: Number,
102:       default: 5
103:     },
104:     fileSize: {
105:       type: Number,
106:       default: 100
107:     },
108:     fileType: {
109:       type: Array,
110:       default: () => ['doc', 'xls', 'ppt', 'txt', 'pdf', 'docx', 'png', 'jpg']
111:     },
112:     disabled: {
113:       type: Boolean,
114:       default: false
115:     },
116:     fileUrl: {
117:       type: String,
118:       default: ''
119:     },
120:     uploadData: {
121:       type: Object,
122:       default: () => ({})
123:     },
124:     /** v-model 为字符串时输出字段：url（zs-file-upload）或 fileSite（FileUpload） */
125:     valueKey: {
126:       type: String,
127:       default: 'url',
128:       validator: (v) => v === 'url' || v === 'fileSite'
129:     }
130:   },
131:   data() {
132:     return {
133:       fileList: [],
134:       uploadPlaceholderImg,
135:       appendixViewEmptyImg,
136:       uploading: false,
137:       uploadPercent: 0,
138:       fileTypeOptions: []
139:     }
140:   },
141:   computed: {
142:     fieldStyleVars() {
143:       return {
144:         '--appendix-thumb-size': `${APPENDIX_THUMB_SIZE}px`,
145:         '--appendix-requirement-grid-gap': `${APPENDIX_REQUIREMENT_GRID_GAP}px`,
146:         '--appendix-requirement-card-min': `${APPENDIX_REQUIREMENT_CARD_MIN_WIDTH}px`,
147:         '--appendix-title-to-thumb-gap': `${APPENDIX_TITLE_TO_THUMB_GAP}px`
148:       }
149:     },
150:     showCardHeader() {
151:       return Boolean(this.label)
152:     },
153:     outerClasses() {
154:       return this.showCardHeader ? ['appendix-requirement-grid', 'standalone-appendix-field-grid'] : []
155:     },
156:     cardCellClass() {
157:       return this.showCardHeader ? 'appendix-requirement-card-cell' : ''
158:     },
159:     headers() {
160:       return {
161:         Authorization: 'Bearer ' + getToken()
162:       }
163:     },
164:     uploadFileUrl() {
165:       const path = this.fileUrl || '/file/file/upload'
166:       if (path.startsWith('http://') || path.startsWith('https://')) {
167:         return path
168:       }
169:       return import.meta.env.VITE_APP_BASE_API + path
170:     },
171:     progressCircleSize() {
172:       return Math.max(APPENDIX_THUMB_SIZE - 60, 48)
173:     },
174:     appendixFiles() {
175:       return this.fileList.map((item) => this.toAppendixFile(item))
176:     },
177:     picFiles() {
178:       return this.appendixFiles.filter((file) => isAppendixImage(file, this.fileTypeOptions))
179:     },
180:     showUploadSlot() {
181:       if (this.disabled || this.uploading) {
182:         return false
183:       }
184:       return this.fileList.length < this.limit
185:     },
186:     showEmptyViewPlaceholder() {
187:       return this.disabled && this.fileList.length === 0
188:     },
189:     mergedUploadData() {
190:       return { ...this.uploadData }
191:     }
192:   },
193:   watch: {
194:     value: {
195:       handler(val) {
196:         this.fileList = this.parseValue(val)
197:       },
198:       deep: true,
199:       immediate: true
200:     }
201:   },
202:   methods: {
203:     parseValue(val) {
204:       if (!val) {
205:         return []
206:       }
207:       if (Array.isArray(val)) {
208:         return val.map((item, index) => this.normalizeIncoming(item, index))
209:       }
210:       if (typeof val === 'object') {
211:         return [this.normalizeIncoming(val, 0)]
212:       }
213:       return String(val)
214:         .split(',')
215:         .map((item) => item.trim())
216:         .filter(Boolean)
217:         .map((site, index) => this.normalizeIncoming(site, index))
218:     },
219:     normalizeIncoming(el, index) {
220:       if (typeof el === 'string') {
221:         const site = el
222:         return {
223:           uid: `-${index}`,
224:           fileSite: site,
225:           url: site,
226:           fileName: extractFileName(site),
227:           name: extractFileName(site)
228:         }
229:       }
230:       const site = el.fileSite || el.fileUrl || el.url || ''
231:       return {
232:         ...el,
233:         uid: el.uid || el.appendixId || nextAppendixUid(),
234:         fileSite: site,
235:         url: site,
236:         fileName: el.fileName || el.name || extractFileName(site),
237:         name: el.fileName || el.name || extractFileName(site)
238:       }
239:     },
240:     toAppendixFile(item) {
241:       const site = item.fileSite || item.url || ''
242:       return {
243:         appendixId: item.uid || item.appendixId || site,
244:         fileSite: site,
245:         fileName: item.fileName || item.name || extractFileName(site),
246:         fileThumbnailSite: item.fileThumbnailSite || site,
247:         fileType: item.type || item.fileType
248:       }
249:     },
250:     handleUploadProgress(event) {
251:       const percent = Math.round(event?.percent ?? 0)
252:       this.uploadPercent = Math.min(100, Math.max(0, percent))
253:     },
254:     handleBeforeUpload(file) {
255:       if (this.fileList.length >= this.limit) {
256:         this.$message.error(`上传文件数量不能超过 ${this.limit} 个!`)
257:         return false
258:       }
259:       if (this.fileType?.length) {
260:         let fileExtension = ''
261:         if (file.name.lastIndexOf('.') > -1) {
262:           fileExtension = file.name.slice(file.name.lastIndexOf('.') + 1).toLowerCase()
263:         }
264:         const isTypeOk = this.fileType.some((type) => {
265:           const normalized = String(type).toLowerCase().replace(/^\./, '')
266:           if (!normalized) return false
267:           if (fileExtension && fileExtension === normalized) {
268:             return true
269:           }
270:           if (file.type && file.type.toLowerCase().includes(normalized)) return true
271:           return false
272:         })
273:         if (!isTypeOk) {
274:           this.$message.error(`文件格式不正确, 请上传${this.fileType.join('/')}格式文件!`)
275:           return false
276:         }
277:       }
278:       if (this.fileSize) {
279:         const isLt = file.size / 1024 / 1024 < this.fileSize
280:         if (!isLt) {
281:           this.$message.error(`上传文件大小不能超过 ${this.fileSize} MB!`)
282:           return false
283:         }
284:       }
285:       this.uploading = true
286:       this.uploadPercent = 0
287:       return true
288:     },
289:     handleExceed() {
290:       this.$message.error(`上传文件数量不能超过 ${this.limit} 个!`)
291:     },
292:     handleUploadError(err) {
293:       this.uploading = false
294:       this.uploadPercent = 0
295:       let message = '上传失败, 请重试'
296:       try {
297:         const errorData = JSON.parse(err?.message || '{}')
298:         message = errorData.msg || message
299:       } catch {
300:         // ignore
301:       }
302:       this.$message.error(message)
303:     },
304:     handleUploadSuccess(res, file) {
305:       if (!res || res.code != 200) {
306:         this.uploading = false
307:         this.uploadPercent = 0
308:         this.$message.error(res?.msg || '上传失败, 请重试')
309:         return
310:       }
311:       this.uploading = false
312:       this.uploadPercent = 0
313:       this.$message.success('上传成功')
314:       const site = res.data?.fileSite || res.data?.url || ''
315:       const uploaded = this.normalizeIncoming(
316:         {
317:           ...res.data,
318:           uid: nextAppendixUid(),
319:           fileSite: site,
320:           url: site,
321:           fileName: res.data?.fileName || file?.name,
322:           name: res.data?.fileName || file?.name,
323:           type: file?.name?.slice(file.name.lastIndexOf('.') + 1)
324:         },
325:         this.fileList.length
326:       )
327:       this.fileList = [...this.fileList, uploaded]
328:       this.emitValue()
329:       this.$emit('getList', this.fileList)
330:     },
331:     handleThumbnailRemove(id) {
332:       const index = this.fileList.findIndex(
333:         (item) => (item.uid || item.appendixId || item.fileSite || item.url) === id
334:       )
335:       if (index === -1) {
336:         return
337:       }
338:       const removed = this.fileList[index]
339:       this.fileList.splice(index, 1)
340:       this.emitValue()
341:       this.$emit('getList', this.fileList)
342:       this.$emit('delete', removed)
343:     },
344:     emitValue() {
345:       if (Array.isArray(this.value)) {
346:         this.$emit('input', this.fileList)
347:         return
348:       }
349:       this.$emit('input', this.listToString(this.fileList))
350:     },
351:     listToString(list, separator = ',') {
352:       const key = this.valueKey
353:       return list
354:         .map((el) => (key === 'fileSite' ? el.fileSite || el.url : el.url || el.fileSite))
355:         .filter(Boolean)
356:         .join(separator)
357:     }
358:   }
359: }
360: </script>
