93: <script>
94: import AppendixFileThumbnail from './AppendixFileThumbnail.vue'
95: import uploadPlaceholderImg from '@/assets/images/annex/upload-file-placeholder.png'
96: import appendixViewEmptyImg from '@/assets/images/annex/appendix-view-empty.png'
97: import { APPENDIX_THUMB_SIZE, getAppendixFileTemplatePaths, isAppendixImage } from '@/utils/appendix.js'
98: import { downloadServerAssetFile } from '@/utils/resolveServerAssetUrl.js'
99: 
100: export default {
101:   name: 'AppendixRequirementCard',
102:   components: { AppendixFileThumbnail },
103:   props: {
104:     item: {
105:       type: Object,
106:       required: true
107:     },
108:     operable: {
109:       type: Boolean,
110:       default: true
111:     },
112:     cardOperable: {
113:       type: Boolean,
114:       default: true
115:     },
116:     multi: {
117:       type: Boolean,
118:       default: false
119:     },
120:     types: {
121:       type: Array,
122:       default: () => []
123:     },
124:     checked: {
125:       type: Array,
126:       default: () => []
127:     },
128:     uploadFileUrl: {
129:       type: String,
130:       required: true
131:     },
132:     headers: {
133:       type: Object,
134:       default: () => ({})
135:     },
136:     uploadData: {
137:       type: Function,
138:       required: true
139:     },
140:     onBeforeUpload: {
141:       type: Function,
142:       required: true
143:     },
144:     onUploadError: {
145:       type: Function,
146:       required: true
147:     },
148:     onExceed: {
149:       type: Function,
150:       required: true
151:     },
152:     onUploadSuccess: {
153:       type: Function,
154:       required: true
155:     },
156:     onRemoveFile: {
157:       type: Function,
158:       default: null
159:     }
160:   },
161:   data() {
162:     return {
163:       checkedList: [],
164:       uploadPlaceholderImg,
165:       appendixViewEmptyImg,
166:       uploading: false,
167:       removing: false,
168:       uploadPercent: 0
169:     }
170:   },
171:   computed: {
172:     progressCircleSize() {
173:       return Math.max(APPENDIX_THUMB_SIZE - 60, 48)
174:     },
175:     showRequiredMark() {
176:       return this.operable && String(this.item.isRequired) === '1'
177:     },
178:     showPictureCardUpload() {
179:       return this.operable && this.cardOperable
180:     },
181:     uploadLimit() {
182:       const max = Number(this.item.fileMaxAmount)
183:       return max > 0 ? max : 1
184:     },
185:     appendices() {
186:       return this.item.appendices || []
187:     },
188:     showUploadSlot() {
189:       if (!this.showPictureCardUpload) {
190:         return false
191:       }
192:       if (this.uploading || this.removing) {
193:         return false
194:       }
195:       return this.appendices.length < this.uploadLimit
196:     },
197:     picFiles() {
198:       return this.appendices.filter((file) => isAppendixImage(file, this.types))
199:     },
200:     /** 非上传态且无附件时展示缺省图 */
201:     showEmptyViewPlaceholder() {
202:       if (this.showPictureCardUpload) {
203:         return false
204:       }
205:       return this.appendices.length === 0
206:     },
207:     templatePaths() {
208:       return getAppendixFileTemplatePaths(this.item)
209:     },
210:     /** 当前要件支持的扩展名（由 fileType 命中字典 remark 汇总，禅道 6035） */
211:     acceptTypeHint() {
212:       const type = this.item.fileType
213:       if (!type || !Array.isArray(this.types)) {
214:         return ''
215:       }
216:       return this.types
217:         .filter((dict) => type.includes(dict.dictValue))
218:         .map((dict) => dict.remark)
219:         .join(',')
220:     }
221:   },
222:   watch: {
223:     checked: {
224:       handler(val) {
225:         this.checkedList = val ? [...val] : []
226:       },
227:       immediate: true,
228:       deep: true
229:     },
230:     appendices: {
231:       handler(val, oldVal) {
232:         const newLen = val ? val.length : 0
233:         const prevLen = oldVal ? oldVal.length : 0
234:         if (this.uploading && (newLen > prevLen || newLen >= this.uploadLimit)) {
235:           this.uploading = false
236:           this.uploadPercent = 0
237:         }
238:         if (this.removing && newLen < prevLen) {
239:           this.removing = false
240:         }
241:       },
242:       deep: true
243:     }
244:   },
245:   methods: {
246:     /** 带出件无 appendixId，需按路径兜底保证列表 key 唯一 */
247:     fileKey(file) {
248:       return file?.appendixId || file?.fileSite || file?.fileName
249:     },
250:     /** 预填带出件（fileSource='2'）只读，不可删除 */
251:     isFileOperable(file) {
252:       return String(file?.fileSource ?? '') !== '2'
253:     },
254:     handleUploadProgress(event) {
255:       const percent = Math.round(event?.percent ?? 0)
256:       this.uploadPercent = Math.min(100, Math.max(0, percent))
257:     },
258:     /**
259:      * el-upload 的 before-upload：只有同步返回 false 才会阻断上传。
260:      * 这里不能写成 async —— async 恒返回 Promise，而 el-upload 的 Promise 分支只在
261:      * resolve 出 File/Blob 时才采用其返回值，resolve 成 false 依旧会 post 原文件，
262:      * 造成「已经提示格式不支持，但文件仍然传到后端」的双重提示（bug 5798）。
263:      * 异步校验一律用 reject 表达拦截，同步校验保持返回 false/true。
264:      */
265:     handleBeforeUpload(file) {
266:       if (this.uploading || this.appendices.length >= this.uploadLimit) {
267:         return false
268:       }
269:       const startUpload = () => {
270:         this.uploading = true
271:         this.uploadPercent = 0
272:         return true
273:       }
274:       const result = this.onBeforeUpload(file, this.item)
275:       if (result && typeof result.then === 'function') {
276:         return result.then(
277:           (resolved) => (resolved === false
278:             ? Promise.reject(new Error('appendix before-upload rejected'))
279:             : startUpload()),
280:           (error) => Promise.reject(error)
281:         )
282:       }
283:       if (result === false) {
284:         return false
285:       }
286:       return startUpload()
287:     },
288:     handleUploadSuccess(response, file, fileList) {
289:       this.onUploadSuccess(response, file, fileList)
290:       if (!response || response.code != 200) {
291:         this.uploading = false
292:         this.uploadPercent = 0
293:       }
294:     },
295:     handleUploadError(err, file, fileList) {
296:       this.uploading = false
297:       this.uploadPercent = 0
298:       this.onUploadError(err, file, fileList)
299:     },
300:     handleThumbnailRemove(id) {
301:       if (!id) {
302:         return
303:       }
304:       this.removing = true
305:       if (typeof this.onRemoveFile === 'function') {
306:         this.onRemoveFile(id).catch(() => {
307:           this.removing = false
308:         })
309:         return
310:       }
311:       this.$emit('onRemove', id)
312:     },
313:     onCheckboxChange() {
314:       this.$emit('update:checked', this.checkedList)
315:     },
316:     onRemove(id) {
317:       this.$emit('onRemove', id)
318:     },
319:     onDownload(file) {
320:       this.$emit('onDownload', file)
321:     },
322:     async handleDownloadTemplate() {
323:       const paths = this.templatePaths
324:       if (!paths.length) return
325:       try {
326:         for (const path of paths) {
327:           await downloadServerAssetFile(path)
328:         }
329:       } catch (e) {
330:         this.$message?.error?.('模板下载失败，请稍后重试')
331:       }
332:     }
333:   }
334: }
335: </script>
